import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import 'package:go_router/go_router.dart'  import '../api/api_client.dart'  import '../providers/auth_provider.dart'  import 'clients_screen.dart'  import 'deals_screen.dart'  import 'invoices_screen.dart'  import 'tasks_screen.dart'  import 'profile_screen.dart'  import 'notifications_screen.dart'  import 'bank_screen.dart'  import 'svetlana_screen.dart'    class HomeScreen extends ConsumerStatefulWidget {    const HomeScreen({super.key})      @override    ConsumerState<HomeScreen> createState() => _HomeScreenState()  }    class _HomeScreenState extends ConsumerState<HomeScreen> {    int _currentIndex = 0    bool _isLoading = true    Map<String, dynamic> _stats = {}      final _screens = [      const _DashboardTab(),      const ClientsScreen(),      const DealsScreen(),      const InvoicesScreen(),      const TasksScreen(),    ]      @override    void initState() {      super.initState()      _checkAuth()      _loadStats()    }      Future<void> _checkAuth() async {      final isAuth = await ApiClient().isAuthenticated()      if (!isAuth && mounted) {        context.go('/login')        return      }      ref.read(authProvider.notifier).state = true      setState(() => _isLoading = false)    }      Future<void> _loadStats() async {      try {        final stats = await ApiClient().getDashboardStats()        if (mounted) {          setState(() => _stats = stats)          ref.read(unreadCountProvider.notifier).state = stats['unread'] ?? 0        }      } catch (e) {        debugPrint('Stats error: $e')      }    }      @override    Widget build(BuildContext context) {      if (_isLoading) {        return const Scaffold(body: Center(child: CircularProgressIndicator()))      }        return Scaffold(        appBar: AppBar(          title: const Text('Мир Самозанятых'),          actions: [            Stack(              children: [                IconButton(                  icon: const Icon(Icons.notifications_outlined),                  onPressed: () => context.push('/notifications'),                ),                if ((ref.watch(unreadCountProvider)) > 0)                  Positioned(                    right: 8,                    top: 8,                    child: Container(                      padding: const EdgeInsets.all(4),                      decoration: const BoxDecoration(                        color: Colors.red,                        shape: BoxShape.circle,                      ),                      child: Text(                        '${ref.watch(unreadCountProvider)}',                        style: const TextStyle(color: Colors.white, fontSize: 10),                      ),                    ),                  ),              ],            ),            IconButton(              icon: const Icon(Icons.person_outline),              onPressed: () => context.push('/profile'),            ),          ],        ),        body: RefreshIndicator(          onRefresh: _loadStats,          child: _screens[_currentIndex],        ),        bottomNavigationBar: BottomNavigationBar(          currentIndex: _currentIndex,          onTap: (index) => setState(() => _currentIndex = index),          items: const [            BottomNavigationBarItem(icon: Icon(Icons.dashboard_outlined), label: 'Главная'),            BottomNavigationBarItem(icon: Icon(Icons.people_outline), label: 'Клиенты'),            BottomNavigationBarItem(icon: Icon(Icons.handshake_outlined), label: 'Сделки'),            BottomNavigationBarItem(icon: Icon(Icons.receipt_outlined), label: 'Счета'),            BottomNavigationBarItem(icon: Icon(Icons.task_alt), label: 'Задачи'),          ],        ),        floatingActionButton: _currentIndex == 0            ? FloatingActionButton.extended(                onPressed: () => context.push('/svetlana'),                icon: const Icon(Icons.smart_toy),                label: const Text('Светлана'),                backgroundColor: const Color(0xFF7C3AED),              )            : null,      )    }  }    class _DashboardTab extends StatelessWidget {    const _DashboardTab()      @override    Widget build(BuildContext context) {      return SingleChildScrollView(        padding: const EdgeInsets.all(16),        child: Column(          crossAxisAlignment: CrossAxisAlignment.start,          children: [            // Welcome            const Text(              'Добро пожаловать!',              style: TextStyle(fontSize: 24, fontWeight: FontWeight.bold),            ),            const SizedBox(height: 16),              // Stats cards            Row(              children: [                _StatCard(                  icon: Icons.receipt_long,                  label: 'Счетов',                  value: '0',                  color: Colors.blue,                  onTap: () {},                ),                const SizedBox(width: 12),                _StatCard(                  icon: Icons.people,                  label: 'Клиентов',                  value: '0',                  color: Colors.purple,                  onTap: () {},                ),              ],            ),            const SizedBox(height: 12),            Row(              children: [                _StatCard(                  icon: Icons.handshake,                  label: 'Сделок',                  value: '0',                  color: Colors.orange,                  onTap: () {},                ),                const SizedBox(width: 12),                _StatCard(                  icon: Icons.task_alt,                  label: 'Задач',                  value: '0',                  color: Colors.green,                  onTap: () {},                ),              ],            ),            const SizedBox(height: 24),              // Quick actions            const Text(              'Быстрые действия',              style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold),            ),            const SizedBox(height: 12),            _QuickActionCard(              icon: Icons.account_balance,              title: 'Банк',              subtitle: 'Синхронизация с Тинькофф',              color: Colors.blue,              onTap: () => context.push('/bank'),            ),            const SizedBox(height: 8),            _QuickActionCard(              icon: Icons.receipt,              title: 'Чеки ФНС',              subtitle: 'Проверка чеков',              color: Colors.green,              onTap: () {},            ),            const SizedBox(height: 8),            _QuickActionCard(              icon: Icons.calculate,              title: 'Налоги',              subtitle: 'Расчет налогов УСН/НПД',              color: Colors.orange,              onTap: () {},            ),          ],        ),      )    }  }    class _StatCard extends StatelessWidget {    final IconData icon    final String label    final String value    final Color color    final VoidCallback onTap      const _StatCard({      required this.icon,      required this.label,      required this.value,      required this.color,      required this.onTap,    })      @override    Widget build(BuildContext context) {      return Expanded(        child: Card(          child: InkWell(            onTap: onTap,            borderRadius: BorderRadius.circular(12),            child: Padding(              padding: const EdgeInsets.all(16),              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  Icon(icon, color: color, size: 28),                  const SizedBox(height: 12),                  Text(                    value,                    style: const TextStyle(fontSize: 24, fontWeight: FontWeight.bold),                  ),                  const SizedBox(height: 4),                  Text(                    label,                    style: TextStyle(fontSize: 12, color: Colors.grey[600]),                  ),                ],              ),            ),          ),        ),      )    }  }    class _QuickActionCard extends StatelessWidget {    final IconData icon    final String title    final String subtitle    final Color color    final VoidCallback onTap      const _QuickActionCard({      required this.icon,      required this.title,      required this.subtitle,      required this.color,      required this.onTap,    })      @override    Widget build(BuildContext context) {      return Card(        child: ListTile(          leading: Container(            padding: const EdgeInsets.all(10),            decoration: BoxDecoration(              color: color.withOpacity(0.1),              borderRadius: BorderRadius.circular(10),            ),            child: Icon(icon, color: color),          ),          title: Text(title, style: const TextStyle(fontWeight: FontWeight.w600)),          subtitle: Text(subtitle, style: TextStyle(fontSize: 12, color: Colors.grey[600])),          trailing: const Icon(Icons.chevron_right, color: Colors.grey),          onTap: onTap,        ),      )    }  }